## CHAPTER lexer

The DSL is lexed by a hand-written scanner rather than `re.finditer` or a third-party tokenizer for three reasons: precise line and column on every token so parser errors can point at a column, first-class duration literals like `30s` and `1m` that would otherwise need post-processing, and deterministic maximal-munch behavior for two-character operators such as `==` and `&&`. The lexer is a single pass with one character of lookahead and produces a flat token list ending in an `EOF` sentinel, which frees the parser from bounds checking.

Token kinds are: `IDENT` for `[A-Za-z_][A-Za-z0-9_-]*`, `STRING` for double-quoted text with escapes `\n`, `\t`, `\"`, `\\`, `NUMBER` for integer and decimal digits, `DURATION` for a number suffixed with `ms`, `s`, `m`, or `h`, `OP` for the six comparison and logical operators, `PUNCT` for structural characters `{ } = , [ ] ( ) : < > ! +`, `NEWLINE`, and `EOF`. Keywords such as `task`, `true`, and `env` are deliberately *not* reserved at lex time; the parser interprets `IDENT` values in context, which keeps the lexer reusable for the expression grammar in chapter 5.

Comments start with `#` and run to end of line; they are skipped without emitting a token, but the newline that terminates them is still emitted so line-oriented field parsing works. Whitespace between tokens is skipped. An unterminated string, a bad escape, a bare number glued to letters (`30x`), or any unexpected character raises `LexError` carrying line, column, and a human-readable reason.

**Invariants.** (L1) Concatenating token source text plus skipped whitespace and comments reproduces the input exactly, which makes column arithmetic trustworthy. (L2) The final token is always `EOF`; the parser can never read past it because `next()` refuses to advance at `EOF`. (L3) A `DURATION` token is always followed by a non-identifier character or end of input; `30sleep` is a lex error, not a number plus identifier.

**Error handling.** `LexError` subclasses `ValueError` and formats as `line:col: message`, matching `ParseError` so chapter 6 can merge both into one error list. The lexer fails fast on the first error; the parser, not the lexer, implements multi-error recovery by resynchronizing at the next newline or `task` keyword.

**Worked example.** For the three-line sample in the demo, the stream begins with `IDENT 'task'`, `IDENT 'lint'`, `PUNCT ':'`, then on line two `IDENT 'timeout'`, `PUNCT '='`, `DURATION '30s'`; the comment contributes nothing, and line three yields `IDENT 'when'`, `PUNCT '='`, `IDENT 'env'`, `PUNCT '.'`, `IDENT 'CI'`, `OP '!='`, `STRING 'false'`. The trailing token is `EOF` at line 4, column 1.

```python
# taskrun/lexer.py
from __future__ import annotations

import re
from dataclasses import dataclass


class LexError(ValueError):
    def __init__(self, msg: str, line: int, col: int) -> None:
        super().__init__(f"{line}:{col}: {msg}")
        self.line, self.col = line, col


@dataclass
class Token:
    kind: str        # IDENT STRING NUMBER DURATION OP PUNCT NEWLINE EOF
    value: str
    line: int
    col: int


IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_\-]*")
NUMBER_RE = re.compile(r"\d+(?:\.\d+)?")
DURATION_RE = re.compile(r"\d+(?:\.\d+)?(?:ms|s|m|h)")
TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "&&", "||")
ONE_CHAR = set("{}[]=(),:<>!")


class Lexer:
    def __init__(self, text: str) -> None:
        self.text, self.i, self.line, self.col = text, 0, 1, 1

    def _peek(self, off: int = 0) -> str:
        j = self.i + off
        return self.text[j] if j < len(self.text) else ""

    def _advance(self, n: int = 1) -> None:
        for _ in range(n):
            if self.i < len(self.text):
                if self.text[self.i] == "\n":
                    self.line, self.col = self.line + 1, 1
                else:
                    self.col += 1
                self.i += 1

    def tokens(self) -> list[Token]:
        out: list[Token] = []
        while self.i < len(self.text):
            ch = self._peek()
            if ch in " \t\r":
                self._advance()
            elif ch == "#":
                while self._peek() not in ("", "\n"):
                    self._advance()
            elif ch == "\n":
                out.append(Token("NEWLINE", "\\n", self.line, self.col))
                self._advance()
            elif ch == '"':
                out.append(self._string())
            elif ch.isdigit():
                out.append(self._number_or_duration())
            elif ch.isalpha() or ch == "_":
                m = IDENT_RE.match(self.text, self.i)
                out.append(Token("IDENT", m.group(0), self.line, self.col))
                self._advance(len(m.group(0)))
            elif self._peek(0) + self._peek(1) in TWO_CHAR_OPS:
                out.append(Token("OP", self._peek(0) + self._peek(1), self.line, self.col))
                self._advance(2)
            elif ch in ONE_CHAR:
                out.append(Token("PUNCT", ch, self.line, self.col))
                self._advance()
            else:
                raise LexError(f"unexpected character {ch!r}", self.line, self.col)
        out.append(Token("EOF", "", self.line, self.col))
        return out

    def _string(self) -> Token:
        line, col = self.line, self.col
        self._advance()
        buf: list[str] = []
        while True:
            ch = self._peek()
            if ch in ("", "\n"):
                raise LexError("unterminated string", line, col)
            if ch == '"':
                self._advance()
                return Token("STRING", "".join(buf), line, col)
            if ch == "\\":
                nxt = self._peek(1)
                mapping = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}
                if nxt not in mapping:
                    raise LexError(f"bad escape \\{nxt}", self.line, self.col)
                buf.append(mapping[nxt])
                self._advance(2)
            else:
                buf.append(ch)
                self._advance()

    def _number_or_duration(self) -> Token:
        line, col = self.line, self.col
        m = DURATION_RE.match(self.text, self.i)
        if m and not self.text[m.end():m.end() + 1].isalnum():
            self._advance(len(m.group(0)))
            return Token("DURATION", m.group(0), line, col)
        m = NUMBER_RE.match(self.text, self.i)
        nxt = self.text[m.end():m.end() + 1]
        if nxt and (nxt.isalpha() or nxt == "_"):
            raise LexError(f"bare number followed by {nxt!r}; units are ms s m h", line, col)
        self._advance(len(m.group(0)))
        return Token("NUMBER", m.group(0), line, col)


if __name__ == "__main__":
    sample = 'task lint:\n    timeout = 30s   # seconds\n'
    for tok in Lexer(sample).tokens():
        print(f"{tok.line}:{tok.col:>2} {tok.kind:<9} {tok.value!r}")
```

## CHAPTER parser

The parser is a recursive-descent translator from the token stream to `TaskSpec` objects plus an expression AST. The grammar is line-oriented: a file is a sequence of `task <name>:` headers, each followed by `key = expression` fields until the next header or EOF. Field keys are restricted to `needs`, `command`, `timeout`, `retry`, `when`, and `description`; unknown keys are rejected with a `difflib` "did you mean" hint, which catches the classic `timeoutt` typo.

Expression precedence, lowest to highest, is `||`, `&&`, unary `!`, a single non-associative comparison (`== != < <= > >=`), then primaries: string, number, duration, `true`, `false`, `env.<NAME>`, function calls `name(args, key=value)`, bracketed lists, and parenthesized groups. A bare identifier parses as `Const(name)` so `needs = [lint, test]` works; the validator in chapter 6 rejects bare identifiers where they make no sense. Function calls accept positional and keyword arguments, which is exactly what the `tool(...)` and `retry` builders need.

Structural errors, such as a missing colon after the task name, are fatal to that task but not to the file: `parse_file` records the `ParseError`, then `_sync_to_next_task` skips tokens to the next `task NAME` pair, so one broken task does not hide five others. Field-level errors are capped at 20 to keep diagnostics bounded. Two DSL constructs are translated eagerly: `retry` builders (`none()`, `fixed(attempts, delay, backoff)`, `exponential(...)` with `max_delay`) become `RetrySpec`, and `command` builders (`tool(name, **params)` and `argv([...])`) become `CommandSpec`. Durations are converted to float seconds at parse time, so `timeout = 90s` and `timeout = 1.5m` both arrive as `90.0`.

**Invariants.** (P1) The parser never evaluates `env` references or spawns anything; `when` remains an AST until the scheduler evaluates it in chapter 9. (P2) Every `TaskSpec` reaching chapter 6 has syntactically valid needs (a `ListLit` of strings) and a converted or absent `command` and `retry`. (P3) Parse errors always include line and column taken from the offending token.

**Error handling.** `ParseError` wraps the failing token, and field errors are re-raised prefixed with the task name so a message reads `task 'test': 4:11: unknown dependency syntax`. The `errors` list on `TaskFile` is merged with semantic errors in chapter 6, giving the user the complete problem list in one run.

**Worked example.** Parsing the demo file yields two tasks: `lint` with `needs=()`, `timeout_s=30.0`, `command=CommandSpec(kind='tool', tool='lint', params={'target': 'src/'})`, and `retry=RetrySpec(attempts=2, delay_s=2.0)`; and `test` with `needs=('lint',)`, `when=Binary('!=', EnvRef('CI'), Const('false'))`. The printed errors list is empty, and the AST printout shows the un-evaluated expression tree.

```python
# taskrun/parser.py
from __future__ import annotations

import difflib
from dataclasses import dataclass

from taskrun.core import CommandSpec, RetrySpec, TaskSpec
from taskrun.lexer import Lexer, Token

FIELD_KEYS = {"needs", "command", "timeout", "retry", "when", "description"}
COMPARISONS = {"==", "!=", "<", "<=", ">", ">="}
MAX_ERRORS = 20


class ParseError(Exception):
    def __init__(self, msg: str, tok: Token) -> None:
        super().__init__(f"{tok.line}:{tok.col}: {msg}")


@dataclass(frozen=True)
class Const:
    value: object


@dataclass(frozen=True)
class EnvRef:
    name: str


@dataclass(frozen=True)
class ListLit:
    items: tuple


@dataclass(frozen=True)
class Unary:
    op: str
    operand: object


@dataclass(frozen=True)
class Binary:
    op: str
    left: object
    right: object


@dataclass(frozen=True)
class Call:
    name: str
    args: tuple
    kwargs: dict


@dataclass
class TaskFile:
    tasks: list
    errors: list[str]


class Parser:
    def __init__(self, tokens: list[Token]) -> None:
        self.toks, self.pos = tokens, 0

    def peek(self, off: int = 0) -> Token:
        return self.toks[min(self.pos + off, len(self.toks) - 1)]

    def next(self) -> Token:
        tok = self.toks[self.pos]
        if tok.kind != "EOF":
            self.pos += 1
        return tok

    def expect(self, kind: str, value: str | None = None) -> Token:
        tok = self.peek()
        if tok.kind != kind or (value is not None and tok.value != value):
            raise ParseError(f"expected {value or kind!r}, found {tok.value or tok.kind!r}", tok)
        return self.next()

    def parse_file(self) -> TaskFile:
        tasks, errors = [], []
        while self.peek().kind != "EOF":
            while self.peek().kind == "NEWLINE":
                self.next()
            if self.peek().kind == "EOF":
                break
            try:
                tasks.append(self.parse_task())
            except ParseError as exc:
                errors.append(str(exc))
                if len(errors) >= MAX_ERRORS:
                    break
                self._sync_to_next_task()
        return TaskFile(tasks=tasks, errors=errors)

    def _sync_to_next_task(self) -> None:
        while self.peek().kind != "EOF":
            if (self.peek().kind == "IDENT" and self.peek().value == "task"
                    and self.peek(1).kind == "IDENT"):
                return
            self.next()

    def parse_task(self) -> "TaskSpec":
        self.expect("IDENT", "task")
        name = self.expect("IDENT")
        self.expect("PUNCT", ":")
        spec = TaskSpec(name=name.value)
        while not (self.peek().kind == "IDENT" and self.peek().value == "task"
                   and self.peek(1).kind == "IDENT") and self.peek().kind != "EOF":
            if self.peek().kind == "NEWLINE":
                self.next()
                continue
            self.parse_field(spec)
        return spec

    def parse_field(self, spec: "TaskSpec") -> None:
        key = self.expect("IDENT")
        self.expect("PUNCT", "=")
        if key.value not in FIELD_KEYS:
            close = difflib.get_close_matches(key.value, FIELD_KEYS, 1)
            hint = f" (did you mean {close[0]!r}?)" if close else ""
            raise ParseError(f"unknown field {key.value!r}{hint}", key)
        expr = self.parse_or()
        self._end
